import React, { useEffect, useState, useMemo } from 'react';
import { useDispatch, useSelector } from 'react-redux';
import { useIntl } from 'react-intl';
import api from 'services/api';
import humps from 'humps';
import { selectCurrentWorkspace } from 'store/Faraday/selectors';
import SpinnerComponent from 'Common/Components/SpinnerContainer';
import {
  Empty,
  FilterButton
} from '../common/styled';
import {
  Wrapper,
  ColumnHeader,
  ColumnLabelId,
  ColumnLabelName,
  ColumnLabelTags,
  ContentWrapper,
  FindingItem,
  SeverityBadge,
  FindingInfo,
  FindingName,
  FindingExposure,
  FindingAsset,
  TagsCell,
  TagChip,
  TagsOverflow,
  LatestVulnsIcon,
  ColumnLabelAssets
} from './styled';
import { Divider } from '@material-ui/core';
import { redirect } from 'store/Router/actions';
import { buildExposureDetail, getSeverityInfo, getVisibleTags } from './utils';
import LATEST_FINDINGS_QUERY from './constants';
import TitleWrapper from '../components/TitleWrapper';

const GeneralLatestFindings = () => {
  const dispatch = useDispatch();

  const workspaceSelected = useSelector((state) =>
    selectCurrentWorkspace(state)
  );

  const [vulns, setVulns] = useState([]);
  const [isFetching, setIsFetching] = useState(false);

  const intl = useIntl();
  const translations = useMemo(
    () => ({
      title: intl.formatMessage({
        id: 'dashboard.widgets.latestFindings.title'
      }),
      empty: intl.formatMessage({
        id: 'dashboard.widgets.latestFindings.empty'
      }),
      columnSeverity: intl.formatMessage({
        id: 'dashboard.widgets.latestFindings.columnSeverity'
      }),
      columnName: intl.formatMessage({
        id: 'dashboard.widgets.latestFindings.columnName'
      }),
      assets: intl.formatMessage({
        id: 'dashboard.widgets.latestFindings.columnAssets'
      }),
      columnTags: intl.formatMessage({
        id: 'dashboard.widgets.latestFindings.columnTags'
      }),
      viewAllVulnerabilities: intl.formatMessage({
        id: 'dashboard.widgets.viewAllVulnerabilities'
      })
    }),
    [intl]
  );

  useEffect(() => {
    let mounted = true;

    const fetchVulns = async () => {
      try {
        setIsFetching(true);

        const response = await api.manage.newGetVulns(
          workspaceSelected,
          LATEST_FINDINGS_QUERY
        );

        if (!mounted) return;

        const camelized = humps.camelizeKeys(response);
        setVulns(camelized?.vulnerabilities ?? []);
      } catch (e) {
        if (mounted) setVulns([]);
      } finally {
        if (mounted) setIsFetching(false);
      }
    };

    if (workspaceSelected) fetchVulns();

    return () => {
      mounted = false;
    };
  }, [workspaceSelected]);

  if (isFetching) return <SpinnerComponent height="250px" />;

  return (
    <Wrapper>
      <TitleWrapper
        title={ translations.title }
        info={
          <FilterButton
            onClick={ () => dispatch(redirect(`/manage/${workspaceSelected}`)) }
          >
            {translations.viewAllVulnerabilities}
          </FilterButton>
        }
        icon={ <LatestVulnsIcon /> }
      />
      {vulns.length === 0
        ? (
        <Empty>{translations.empty}</Empty>
          )
        : (
        <>
          <Divider style={ { margin: '16px 0 0 0' } } />
          <ColumnHeader>
           <ColumnLabelId> </ColumnLabelId>
            <ColumnLabelName>
              {translations.columnSeverity} / {translations.columnName}
            </ColumnLabelName>
            <ColumnLabelTags>{translations.columnTags}</ColumnLabelTags>
            <ColumnLabelAssets>{translations.assets}</ColumnLabelAssets>
          </ColumnHeader>
          <ContentWrapper>
            {vulns.map((vuln) => {
              const data = vuln.value ?? {};
              const severityInfo = getSeverityInfo(data.severity);
              const exposureDetail = buildExposureDetail(vuln);
              const { visible: visibleTags, overflow: overflowTags, extraCount } = getVisibleTags(data.tags);

              return (
                <FindingItem key={ vuln.id }>
                  <SeverityBadge color={ severityInfo.color }>
                    {severityInfo.shortLabel}
                  </SeverityBadge>
                  <FindingInfo>
                    <FindingName>{data.name}</FindingName>
                    {exposureDetail && (
                      <FindingExposure>{exposureDetail}</FindingExposure>
                    )}
                  </FindingInfo>
                  <TagsCell>
                    {visibleTags.map((tag) => (
                      <TagChip key={ tag } title={ tag }>{tag}</TagChip>
                    ))}
                    {extraCount > 0 && (
                      <TagsOverflow title={ overflowTags.join(', ') }>
                        +{extraCount}
                      </TagsOverflow>
                    )}
                  </TagsCell>
                  <FindingAsset title={ data?.target ?? '' }>
                    {data?.target ?? ''}
                  </FindingAsset>
                </FindingItem>
              );
            })}
          </ContentWrapper>
        </>
          )}
    </Wrapper>
  );
};

export default GeneralLatestFindings;
